WITH "g1" AS (SELECT "t1"."region" AS "region", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "net_revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."region") SELECT "g1"."region" AS "region", "g1"."net_revenue" AS "net_revenue", "g1"."net_revenue" * 1.0 / NULLIF(SUM("g1"."net_revenue") OVER (), 0) * 100 AS "share_pct" FROM "g1" ORDER BY "net_revenue" DESC LIMIT 1000
